#dia-svg .side{stroke:none}
.plate .top,.rim .top{fill:var(--hi)}.plate .sl,.rim .sl{fill:var(--mid)}.plate .sd,.rim .sd{fill:var(--lo)}
.bearing .top,.screw .top,.knob .top{fill:var(--mid)}.bearing .side,.screw .side,.knob .side{fill:var(--lo)}
