// Modelo puro do diafragma de 9 lâminas. Todas as dimensões em mm.
export const DIM = {
  N: 9,            // número de lâminas
  RP: 20,          // raio do círculo de pivôs
  RC: 20,          // distância pivô -> centro do arco interno da lâmina
  R1: 13,          // raio do arco interno (borda que forma a abertura)
  R2: 19,          // raio do arco externo da lâmina
  Q: [-4.6, 0],    // seguidor no corpo da lâmina (relativo ao pivô)
  F: 50,           // distância focal da lente ideal
  baseZ: [0, 2], bladeT: 0.06, ringZ: [3.2, 4.4],
  ringR: [21.8, 28.6], hole: 11.6, plateR: 33, wallR: [33, 35.2], wallZ: 9,
  Nmin: 2.5, Nmax: 22,
};
const D2R = Math.PI / 180;
// raio da abertura: interseção dos 9 discos do arco interno
// d = |C1 - O| = 2 RC sin(psi/2); r = R1 - d
export function radiusFromPsi(psi) { return DIM.R1 - 2 * DIM.RC * Math.sin(psi / 2); }
export function psiFromRadius(r) { return 2 * Math.asin((DIM.R1 - r) / (2 * DIM.RC)); }
export const PSI_OPEN = psiFromRadius(DIM.F / DIM.Nmin / 2);
export const PSI_CLOSED = psiFromRadius(DIM.F / DIM.Nmax / 2);

// contorno rígido da lâmina, em coordenadas do corpo (pivô na origem, +x para o eixo óptico na posição fechada)
export function bladeOutline() {
  const c = [DIM.RC * Math.cos(PSI_CLOSED), DIM.RC * Math.sin(PSI_CLOSED)];
  const pts = [], lo = 195, hi = 335;
  for (let g = lo; g <= hi; g += 2) pts.push([c[0] + DIM.R1 * Math.cos(g * D2R), c[1] + DIM.R1 * Math.sin(g * D2R)]);
  for (let g = hi; g >= lo; g -= 2) {
    const u = Math.max(0, Math.min(1, (g - 220) / 35));
    let r = 27 - 8 * u * u * (3 - 2 * u);
    // A fixed manufactured outline fits inside the ring throughout its full travel.
    for (let j=0;j<=64;j++) {
      const psi=PSI_OPEN+(PSI_CLOSED-PSI_OPEN)*j/64,b=Math.PI+psi-PSI_CLOSED;
      const ax=DIM.RP+c[0]*Math.cos(b)-c[1]*Math.sin(b),ay=c[0]*Math.sin(b)+c[1]*Math.cos(b);
      const dx=Math.cos(g*D2R+b),dy=Math.sin(g*D2R+b),dot=ax*dx+ay*dy;
      r=Math.min(r,-dot+Math.sqrt(dot*dot+27.6*27.6-ax*ax-ay*ay));
    }
    pts.push([c[0] + r * Math.cos(g * D2R), c[1] + r * Math.sin(g * D2R)]);
  }
  return pts;
}
export const BLADE = bladeOutline();

function rot(p, a) { const c = Math.cos(a), s = Math.sin(a); return [p[0] * c - p[1] * s, p[0] * s + p[1] * c]; }
function bladeFrame(i, psi) {
  const th = i * 2 * Math.PI / DIM.N;
  const piv = [DIM.RP * Math.cos(th), DIM.RP * Math.sin(th)];
  const beta = psi - PSI_CLOSED;          // rotação rígida da lâmina sobre o pivô
  const frameAng = th + Math.PI + beta;   // corpo: +x aponta ao centro na posição fechada
  return { th, piv, beta, frameAng };
}
export function toWorld(i, psi, p) {
  const f = bladeFrame(i, psi); const q = rot(p, f.frameAng);
  return [f.piv[0] + q[0], f.piv[1] + q[1]];
}
function pinAngle(psi) { const w = toWorld(0, psi, DIM.Q); return Math.atan2(w[1], w[0]); }
const PIN0 = pinAngle(PSI_CLOSED);
export function ringAngle(psi) { return pinAngle(psi) - PIN0; } // rad; rasgos radiais seguem o pino
export const ALPHA_OPEN = ringAngle(PSI_OPEN);

export function toWorld3D(i,psi,p) {
  const xy=toWorld(i,psi,p);return [xy[0],xy[1],DIM.baseZ[1]+.65+.016*p[1]];
}
export function pose(state) {
  const psi = state.psi;
  const blades = [];
  for (let i = 0; i < DIM.N; i++) {
    const f = bladeFrame(i, psi);
    blades.push({ i, pivot: f.piv, beta: f.beta, z: DIM.baseZ[1] + .65,
      outline: BLADE.map(p => toWorld(i, psi, p)), surface: BLADE.map(p=>toWorld3D(i,psi,p)), pin: toWorld(i, psi, DIM.Q) });
  }
  const alpha = ringAngle(psi);
  const slots = blades.map(b => ({ angle: Math.atan2(b.pin[1], b.pin[0]), pin: b.pin }));
  return { blades, alpha, slots, r: radiusFromPsi(psi), psi };
}
export function slotRange() {
  let lo = 1e9, hi = -1e9;
  for (let k = 0; k <= 40; k++) { const p = PSI_OPEN + (PSI_CLOSED - PSI_OPEN) * k / 40; const w = toWorld(0, p, DIM.Q); const r = Math.hypot(w[0], w[1]); lo = Math.min(lo, r); hi = Math.max(hi, r); }
  return [lo, hi];
}

export function readout(psi) {
  const r = radiusFromPsi(psi), D = 2 * r, N = DIM.F / D;
  const area = Math.PI * r * r;
  const ref = Math.PI * Math.pow(DIM.F / 2.8 / 2, 2);
  return { D, N, area, flux: area / ref * 100, alpha: ringAngle(psi) / D2R, beta: (psi - PSI_CLOSED) / D2R,
    travel: ringAngle(psi) / ALPHA_OPEN * 100 };
}
export const psiFromN = N => psiFromRadius(DIM.F / N / 2);
// curso 0..100 % do anel -> psi (bisseção; ringAngle é monótono)
export function psiFromTravel(t) {
  const target = ALPHA_OPEN * Math.max(0, Math.min(100, t)) / 100;
  let a = PSI_OPEN, b = PSI_CLOSED;
  for (let k = 0; k < 50; k++) { const m = (a + b) / 2; const v = ringAngle(m); if ((v - target) * (ALPHA_OPEN > 0 ? 1 : -1) > 0) a = m; else b = m; }
  return (a + b) / 2;
}

export function initial() { const p = psiFromN(2.8); return { psi: p, target: p, cycling: false, phase: 0, msg: 'Pronto: anel em f/2.8.', blocked: false }; }
const near = (a, b) => Math.abs(a - b) < 1e-6;
export function setN(s, N) { const p = psiFromN(N); return { ...s, target: p, cycling: false, blocked: false, msg: 'Preset f/' + N + ' selecionado.' }; }
export function setTravel(s, t) { return { ...s, target: psiFromTravel(t), cycling: false, blocked: false, msg: 'Anel girado manualmente.' }; }
export function stop(s, dir) { // dir +1 abre, -1 fecha (um ponto inteiro: área x2 ou /2)
  const N = readout(s.target).N; let nN = dir > 0 ? N / Math.SQRT2 : N * Math.SQRT2;
  const lim = dir > 0 ? DIM.Nmin : DIM.Nmax;
  if (near(s.target, psiFromN(lim)) || (dir > 0 ? N <= lim + 1e-6 : N >= lim - 1e-6))
    return { ...s, cycling: false, blocked: true, msg: dir > 0 ? 'Bloqueado: batente de abertura máxima f/2.5 — o seguidor está no fim do rasgo.' : 'Bloqueado: batente de fechamento f/22 — as lâminas já se tocam no anel mínimo.' };
  nN = dir > 0 ? Math.max(lim, nN) : Math.min(lim, nN);
  return { ...s, target: psiFromN(nN), cycling: false, blocked: false, msg: (dir > 0 ? 'Aberto' : 'Fechado') + ' um ponto: f/' + nN.toFixed(1) + '.' };
}
export function toggleCycle(s) { return { ...s, cycling: !s.cycling, blocked: false, msg: s.cycling ? 'Ciclo pausado.' : 'Ciclo em andamento.' }; }
// avanço temporal: a pose física interpola até o alvo
export function step(s, dt, instant) {
  let n = { ...s };
  if (n.cycling) { n.phase = (n.phase + dt * 0.25) % 1; n.target = PSI_OPEN + (PSI_CLOSED - PSI_OPEN) * (0.5 - 0.5 * Math.cos(n.phase * 2 * Math.PI)); }
  if (instant) n.psi = n.target; else {
    const d = n.target - n.psi, m = 0.5 * dt; n.psi = Math.abs(d) <= m ? n.target : n.psi + Math.sign(d) * m;
  }
  return n;
}

