import * as M from './model.mjs';
import * as Geo from './geometry.mjs';

const W = 640, H = 470;
export function mount(root, env) {
  let state = M.initial();
  let reduced = !!env.reducedMotion, visible = true, raf = 0, last = 0;
  root.classList.add('dia');
  root.innerHTML = `
  <div class="dia-card">
    <svg id="dia-svg" viewBox="0 0 ${W} ${H}" role="img" aria-label="Diafragma de nove lâminas em vista isométrica, sem tampa">
      <g id="dia-static"></g><g id="dia-moving"></g>
    </svg>
    <p class="dia-inspection-hint">Inspeção: anel e placa de retenção em transparência para revelar as ligações das lâminas.</p><ol class="dia-legend" aria-label="Legenda">
      <li><b>1</b> Lâmina rígida de aço</li><li><b>2</b> Pivô fixo na placa</li><li><b>3</b> Seguidor da lâmina</li>
      <li><b>4</b> Anel de comando e rasgo</li><li><b>5</b> Alavanca do anel</li><li><b>6</b> Parafuso da placa-base</li>
    </ol>
    <div class="dia-read" aria-live="polite">
      <div><span>Número f</span><output id="dia-n"></output></div>
      <div><span>Diâmetro inscrito</span><output id="dia-d"></output></div>
      <div><span>Área inscrita</span><output id="dia-a"></output></div>
      <div><span>Fluxo vs f/2.8</span><output id="dia-flux"></output></div>
      <div><span>Anel α / lâmina β</span><output id="dia-ang"></output></div>
    </div>
    <div class="dia-ctl">
      <label for="dia-travel">Curso do anel <output id="dia-tv"></output></label>
      <input id="dia-travel" type="range" min="0" max="100" step="0.5">
      <div class="dia-row" role="group" aria-label="Presets">
        <button id="dia-p28" type="button">f/2.8</button><button id="dia-p56" type="button">f/5.6</button>
        <button id="dia-p11" type="button">f/11</button><button id="dia-p16" type="button">f/16</button>
      </div>
      <div class="dia-row">
        <button id="dia-open" type="button">Abrir 1 ponto</button><button id="dia-close" type="button">Fechar 1 ponto</button>
        <button id="dia-inspect" type="button" aria-pressed="false">Ver ligação</button><button id="dia-axial" type="button" aria-pressed="false">Vista axial</button><button id="dia-zoom" type="button" aria-pressed="false">Ver de perto</button><button id="dia-cycle" type="button" aria-pressed="false">Animar ciclo</button><button id="dia-reset" type="button">Reiniciar</button>
      </div>
      <p id="dia-status" class="dia-status" role="status"></p>
    </div>
  </div>`;
  const $ = id => root.querySelector('#' + id);
  const svg = $('dia-svg');
  let cam = Geo.makeCamera(W, H);
  $('dia-static').innerHTML = Geo.drawStatic(cam); // sólidos estáticos: uma única vez
  svg.setAttribute('viewBox', cam.vb.map(v => v.toFixed(1)).join(' '));
  let lastPsi = null;
  function draw() {
    if (state.psi !== lastPsi) { $('dia-moving').innerHTML = Geo.drawMoving(cam, M.pose(state), { labels: true }); lastPsi = state.psi; }
    const r = M.readout(state.psi);
    $('dia-n').textContent = 'f/' + r.N.toFixed(1);
    $('dia-d').textContent = r.D.toFixed(2) + ' mm';
    $('dia-a').textContent = r.area.toFixed(1) + ' mm²';
    $('dia-flux').textContent = r.flux.toFixed(0) + ' %';
    $('dia-ang').textContent = r.alpha.toFixed(2) + '° / ' + r.beta.toFixed(1) + '°';
    const tr = M.readout(state.target).travel;
    $('dia-tv').textContent = tr.toFixed(0) + ' %';
    if (document.activeElement !== $('dia-travel') || state.cycling) $('dia-travel').value = tr.toFixed(1);
    $('dia-status').textContent = state.msg;
    $('dia-status').classList.toggle('blocked', state.blocked);
    $('dia-cycle').textContent = state.cycling ? 'Pausar ciclo' : 'Animar ciclo';
    $('dia-cycle').setAttribute('aria-pressed', String(state.cycling));
  }
  function loop(t) {
    raf = 0;
    const dt = last ? Math.min(0.05, (t - last) / 1000) : 0; last = t;
    state = M.step(state, dt, reduced);
    draw();
    if (visible && (state.cycling || state.psi !== state.target)) raf = requestAnimationFrame(loop); else last = 0;
  }
  function kick() {
    if (reduced && !state.cycling) { state = M.step(state, 0, true); draw(); return; }
    draw(); if (!raf && visible) { last = 0; raf = requestAnimationFrame(loop); }
  }
  const act = fn => () => { state = fn(state); kick(); };
  const on = (id, ev, fn) => $(id).addEventListener(ev, fn);
  let zoomed = false, axial = false, inspect = false;
  on('dia-inspect','click',()=>{
    inspect=!inspect;root.classList.toggle('inspection',inspect);
    $('dia-inspect').textContent=inspect?'Fechar inspeção':'Ver ligação';
    $('dia-inspect').setAttribute('aria-pressed',String(inspect));
  });
  on('dia-axial','click',()=>{
    axial=!axial;zoomed=false;cam=Geo.makeCamera(W,H,axial);
    svg.setAttribute('aria-label',axial?'Diafragma de nove lâminas, vista pelo eixo óptico':'Diafragma de nove lâminas em vista isométrica, sem tampa');
    $('dia-static').innerHTML=Geo.drawStatic(cam);
    svg.setAttribute('viewBox',cam.vb.map(v=>v.toFixed(1)).join(' '));
    lastPsi=null;draw();
    $('dia-axial').textContent=axial?'Vista isométrica':'Vista axial';
    $('dia-axial').setAttribute('aria-pressed',String(axial));
    $('dia-zoom').textContent='Ver de perto';$('dia-zoom').setAttribute('aria-pressed','false');
  });
  on('dia-zoom', 'click', () => {
    zoomed = !zoomed;
    const v = cam.vb;
    const zoom = zoomed ? [v[0]+v[2]*.18, v[1]+v[3]*.16, v[2]*.64, v[3]*.64] : v;
    svg.setAttribute('viewBox', zoom.map(n=>n.toFixed(1)).join(' '));
    $('dia-zoom').textContent=zoomed?'Ver conjunto':'Ver de perto';
    $('dia-zoom').setAttribute('aria-pressed',String(zoomed));
  });
  on('dia-p28', 'click', act(s => M.setN(s, 2.8)));
  on('dia-p56', 'click', act(s => M.setN(s, 5.6)));
  on('dia-p11', 'click', act(s => M.setN(s, 11)));
  on('dia-p16', 'click', act(s => M.setN(s, 16)));
  on('dia-open', 'click', act(s => M.stop(s, 1)));
  on('dia-close', 'click', act(s => M.stop(s, -1)));
  on('dia-cycle', 'click', act(s => { const n = M.toggleCycle(s); return n.cycling && reduced ? { ...n, cycling: false, msg: 'Movimento reduzido: ciclo desativado; use os presets.' } : n; }));
  on('dia-reset', 'click', act(() => ({ ...M.initial(), psi: M.psiFromN(5.6), target: M.psiFromN(5.6), msg: 'Reiniciado em f/5.6.' })));
  on('dia-travel', 'input', e => { state = M.setTravel(state, +e.target.value); kick(); });
  const envH = e => { const d = e.detail || {}; if ('reducedMotion' in d) reduced = !!d.reducedMotion; if ('visible' in d) visible = !!d.visible; if (visible) kick(); else if (raf) { cancelAnimationFrame(raf); raf = 0; } };
  root.addEventListener('figure:environment', envH);
  state = M.step(state, 0, true); draw();
  return () => { if (raf) cancelAnimationFrame(raf); root.removeEventListener('figure:environment', envH); root.innerHTML = ''; };
}

