import {planeThrough,orderSurfaces} from '/leitor/occlusion.mjs';
import * as k from '/kit/iso-kit.mjs';
import {DIM,slotRange} from './model.mjs';
const TAU=2*Math.PI;
const num=n=>n.toFixed(2);
const path=(p,closed=true)=>'M'+p.map(q=>q.map(num).join(',')).join('L')+(closed?'Z':'');
const signedArea=p=>p.reduce((s,a,i)=>{const b=p[(i+1)%p.length];return s+a[0]*b[1]-a[1]*b[0]},0)/2;
export function circle(x,y,r,n=72,a0=0,a1=TAU){return Array.from({length:n},(_,i)=>{const a=a0+(a1-a0)*i/n;return[x+r*Math.cos(a),y+r*Math.sin(a)]})}
export function makeCamera(w,h,axial=false){
 const points=[];
 for(let i=0;i<96;i++){
  const a=i*TAU/96;
  for(const[r,z]of[[33,0],[33,2.8],[28.6,DIM.ringZ[0]],[28.6,DIM.ringZ[1]]])points.push([r*Math.cos(a),r*Math.sin(a),z]);
 }
 for(const a of[-1.06,-.88])for(const z of[DIM.ringZ[0],DIM.ringZ[1]+2])points.push([38*Math.cos(a),38*Math.sin(a),z]);
 const P=k.fitProjection(points,w,h,{pad:22,azimuth:42,elevation:axial?89.9:58});
 const screen=points.map(p=>k.iso(p,P)),xs=screen.map(p=>p[0]),ys=screen.map(p=>p[1]);
 const s=Math.sign(k.depthOf([0,0,1],P)-k.depthOf([0,0,0],P))||1;
 return{P,s,vb:[Math.min(...xs)-9,Math.min(...ys)-5,Math.max(...xs)-Math.min(...xs)+18,Math.max(...ys)-Math.min(...ys)+10]};
}
function prism(cam,rings,z0,z1,cls){
 const {P,s}=cam,project=(p,z)=>k.iso([p[0],p[1],z],P);
 const fixed=rings.map((r,i)=>(signedArea(r)>0)===(i===0)?r:r.slice().reverse());
 const sides=[];
 for(const r of fixed)for(let i=0;i<r.length;i++){
  const a=r[i],b=r[(i+1)%r.length],n=[b[1]-a[1],a[0]-b[0]],m=[(a[0]+b[0])/2,(a[1]+b[1])/2,(z0+z1)/2];
  const facing=(k.depthOf([m[0]+n[0]*.01,m[1]+n[1]*.01,m[2]],P)-k.depthOf(m,P))*s;
  if(facing<=0)continue;
  const lit=(n[0]*.6-n[1]*.8)/(Math.hypot(...n)||1);
  sides.push({depth:k.depthOf(m,P)*s,svg:`<path class="side ${lit>.2?'sl':'sd'}" d="${path([project(a,z0),project(b,z0),project(b,z1),project(a,z1)])}"/>`});
 }
 sides.sort((a,b)=>a.depth-b.depth);
 return `<g class="${cls}">${sides.map(a=>a.svg).join('')}<path class="top" fill-rule="evenodd" d="${fixed.map(r=>path(r.map(p=>project(p,z1)))).join('')}"/></g>`;
}
const cyl=(cam,x,y,r,z0,z1,cls)=>prism(cam,[circle(x,y,r,32)],z0,z1,cls);
function line(cam,points,cls){return `<path class="${cls}" d="${path(points.map(p=>k.iso(p,cam.P)),false)}"/>`}
function screw(cam,x,y,z,a){return cyl(cam,x,y,1.15,z,z+.38,'screw')+line(cam,[[x+.7*Math.cos(a),y+.7*Math.sin(a),z+.4],[x-.7*Math.cos(a),y-.7*Math.sin(a),z+.4]],'slit')}
function marker(cam,p,label){const[x,y]=k.iso(p,cam.P);return `<g class="tag"><circle cx="${num(x)}" cy="${num(y)}" r="5.5"/><text x="${num(x)}" y="${num(y+2.6)}">${label}</text></g>`}
export function drawStatic(cam){
 let out=prism(cam,[circle(0,0,33,120),circle(0,0,DIM.hole,72)],0,2,'plate');
 out+=`<path class="void" d="${path(circle(0,0,DIM.hole-.02).map(p=>k.iso([...p,1.9],cam.P)))}"/>`;
 out+=prism(cam,[circle(0,0,33,120),circle(0,0,31.1,120)],2,2.75,'rim');
 for(let i=0;i<6;i++){const a=i*TAU/6+.35;out+=screw(cam,31.9*Math.cos(a),31.9*Math.sin(a),2.77,a+.7)}
 for(let i=0;i<3;i++){
  const a=i*TAU/3+.9,c=Math.cos(a),s=Math.sin(a);
  const ring=[[27,-1.6],[30.6,-1.6],[30.6,1.6],[27,1.6]].map(([r,t])=>[r*c-t*s,r*s+t*c]);
  out+=prism(cam,[ring],2,DIM.ringZ[0],'bearing');
 }
 return out;
}
function capsule(angle,r0,r1,width){
 const c=Math.cos(angle),s=Math.sin(angle),points=[];
 for(const[rad,start]of[[r1,-Math.PI/2],[r0,Math.PI/2]])for(let j=0;j<=12;j++){
  const a=start+Math.PI*j/12,u=rad+width*Math.cos(a),v=width*Math.sin(a);points.push([u*c-v*s,u*s+v*c]);
 }
 return points;
}
// Resolve opaque leaves against their actual 3D planes, rather than a global part order.
function leafSolids(cam,pose){
 const V=[0,1,2].map(i=>{const p=[0,0,0];p[i]=1;return (k.depthOf(p,cam.P)-k.depthOf([0,0,0],cam.P))*cam.s});
 const faces=[],planes=[];
 for(const b of pose.blades){
  const top=b.surface.map(p=>[p[0],p[1],p[2]+DIM.bladeT]),N=top.length/2;
  const q=[top[0],top[1],top[top.length-2],top[top.length-1]],pl=planeThrough(q[0],q[1],q[2]);planes.push(pl);
  for(let i=0;i<N-1;i++)faces.push({points:[top[i],top[i+1],top[top.length-2-i],top[top.length-1-i]],cls:'blade blade-'+b.i,kind:'top'});
  for(let i=0;i<top.length;i++){
   const a=top[i],z=top[(i+1)%top.length],low=p=>[p[0],p[1],p[2]-DIM.bladeT];
   faces.push({points:[a,z,low(z),low(a)],cls:'blade blade-'+b.i,kind:'side sd'});
   faces.push({points:[a,z],cls:'leaf-edge',kind:'edge',segment:true});
  }
 }
 return orderSurfaces(faces,{planes,view:V}).map(item=>{
  const d=path(item.points.map(p=>k.iso(p,cam.P)),!item.segment);
  return item.segment?`<path class="leaf-edge" d="${d}"/>`:`<g class="${item.cls}"><path class="${item.kind}" d="${d}"/></g>`;
 }).join('');
}

export function drawMoving(cam,pose,opts={}){
 let out=leafSolids(cam,pose);
 for(const b of pose.blades){
  out+=cyl(cam,...b.pivot,.92,2,3.45,'pivot');
  out+=cyl(cam,...b.pivot,1.25,3.3,3.55,'pivot');
  out+=line(cam,[[b.pivot[0]-.55,b.pivot[1],b.z+DIM.bladeT+.3],[b.pivot[0]+.55,b.pivot[1],b.z+DIM.bladeT+.3]],'pivot-mark');
 }
 // The fixed retaining plate masks the outer blade stack and holds the pivot bearings.
 const bearings=pose.blades.map(b=>circle(...b.pivot,1.7,32));
 out+=prism(cam,[circle(0,0,22.5,120),circle(0,0,DIM.hole,96),...bearings],3.0,3.15,'retainer');
 for(const b of pose.blades)out+=cyl(cam,...b.pivot,1.25,3.3,3.55,'pivot');
 const[lo,hi]=slotRange(),slots=pose.slots.map(sl=>capsule(sl.angle,lo-.42,hi+.42,1.2));
 for(const sl of pose.slots)out+=`<path class="slot-well" d="${path(capsule(sl.angle,lo-.42,hi+.42,1.2).map(p=>k.iso([...p,DIM.ringZ[0]-.02],cam.P)))}"/>`;
 for(const b of pose.blades)out+=cyl(cam,...b.pin,.72,b.z+DIM.bladeT,DIM.ringZ[1]+.32,'pin');
 out+=prism(cam,[circle(0,0,DIM.ringR[1],144),circle(0,0,DIM.ringR[0],120),...slots],...DIM.ringZ,'ring');
 // A complete command ring. Each capsule is a real hole with a visible inner wall.
 for(const b of pose.blades)out+=cyl(cam,...b.pin,.72,DIM.ringZ[1],DIM.ringZ[1]+.32,'pin');
 for(let i=0;i<72;i++){
  const a=i*TAU/72+pose.alpha,r0=27.5,r1=i%6===0?28.3:28;
  out+=line(cam,[[r0*Math.cos(a),r0*Math.sin(a),DIM.ringZ[1]+.02],[r1*Math.cos(a),r1*Math.sin(a),DIM.ringZ[1]+.02]],'graduation');
 }
 const a=-.95+pose.alpha,c=Math.cos(a),s=Math.sin(a);
 const lever=[[27,-1.4],[37,-1.4],[37,1.4],[27,1.4]].map(([r,t])=>[r*c-t*s,r*s+t*c]);
 out+=prism(cam,[lever],...DIM.ringZ,'ring');out+=cyl(cam,36.2*c,36.2*s,1.25,DIM.ringZ[1],DIM.ringZ[1]+1.8,'knob');
 if(opts.labels){
  const b=pose.blades[3],mid=b.outline[42];out+=marker(cam,[...mid,b.z+.5],1);
  out+=marker(cam,[...pose.blades[6].pivot,pose.blades[6].z+2],2);
  out+=marker(cam,[...pose.blades[7].pin,DIM.ringZ[1]+1.8],3);
  out+=marker(cam,[25.6*Math.cos(2.6),25.6*Math.sin(2.6),DIM.ringZ[1]+.6],4);
  out+=marker(cam,[36.2*c,36.2*s,DIM.ringZ[1]+3],5);
  out+=marker(cam,[31.9*Math.cos(.35+TAU*5/6),31.9*Math.sin(.35+TAU*5/6),4.2],6);
 }
 return out;
}
